def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    def runs(row):
        result = []
        c = 0
        while c < w:
            if row[c] == 0:
                c += 1
                continue
            seq = []
            while c < w and row[c] != 0:
                seq.append(row[c])
                c += 1
            result.append((c - len(seq), seq))
        return result

    patterns = [seq for _, seq in runs(grid[0])]
    patterns.extend(seq for _, seq in runs(grid[-1]))

    for r in range(1, h - 1):
        for c, color in enumerate(grid[r]):
            if color == 0:
                continue
            seq = next((s for s in patterns if color in s), None)
            if seq is None:
                continue
            start = c - seq.index(color)
            for j, value in enumerate(seq):
                x = start + j
                if 0 <= x < w:
                    out[r][x] = value
    return out
